def _leapfrog_integrator_one_step (target_log_prob_fn,independent_chain_ndims,step_sizes,current_momentum_parts,current_state_parts,current_target_log_prob,current_target_log_prob_grad_parts,state_gradients_are_stopped = False,name = None):# Note on per-variable step sizes: # # Using per-variable step sizes is equivalent to using the same step # size for all variables and adding a diagonal mass matrix in the # kinetic energy term of the Hamiltonian being integrated. This is # hinted at by Neal (2011) but not derived in detail there. # # Let x and v be position and momentum variables respectively. # Let g(x) be the gradient of `target_log_prob_fn(x)`. # Let S be a diagonal matrix of per-variable step sizes. # Let the Hamiltonian H(x, v) = -target_log_prob_fn(x) + 0.5 * ||v||**2. # # Using per-variable step sizes gives the updates # v'  = v  + 0.5 * matmul(S, g(x)) # x'' = x  + matmul(S, v') # v'' = v' + 0.5 * matmul(S, g(x'')) # # Let u = matmul(inv(S), v). # Multiplying v by inv(S) in the updates above gives the transformed dynamics # u'  = matmul(inv(S), v')  = matmul(inv(S), v) + 0.5 * g(x) #                           = u + 0.5 * g(x) # x'' = x + matmul(S, v') = x + matmul(S**2, u') # u'' = matmul(inv(S), v'') = matmul(inv(S), v') + 0.5 * g(x'') #                           = u' + 0.5 * g(x'') # # These are exactly the leapfrog updates for the Hamiltonian # H'(x, u) = -target_log_prob_fn(x) + 0.5 * u^T S**2 u #          = -target_log_prob_fn(x) + 0.5 * ||v||**2 = H(x, v). # # To summarize: # # * Using per-variable step sizes implicitly simulates the dynamics #   of the Hamiltonian H' (which are energy-conserving in H'). We #   keep track of v instead of u, but the underlying dynamics are #   the same if we transform back. # * The value of the Hamiltonian H'(x, u) is the same as the value #   of the original Hamiltonian H(x, v) after we transform back from #   u to v. # * Sampling v ~ N(0, I) is equivalent to sampling u ~ N(0, S**-2). # # So using per-variable step sizes in HMC will give results that are # exactly identical to explicitly using a diagonal mass matrix. with tf.compat.v1.name_scope (name,'hmc_leapfrog_integrator_one_step',[ independent_chain_ndims,step_sizes,current_momentum_parts,current_state_parts,current_target_log_prob,current_target_log_prob_grad_parts ]):# Step 1: Update momentum. proposed_momentum_parts = [ v + 0.5 * tf.cast (eps,v.dtype) * g for v,eps,g in zip (current_momentum_parts,step_sizes,current_target_log_prob_grad_parts) ] # Step 2: Update state. proposed_state_parts = [ x + tf.cast (eps,v.dtype) * v for x,eps,v in zip (current_state_parts,step_sizes,proposed_momentum_parts) ] if state_gradients_are_stopped:proposed_state_parts = [ tf.stop_gradient (x) for x in proposed_state_parts ] # Step 3a: Re-evaluate target-log-prob (and grad) at proposed state. [ proposed_target_log_prob,proposed_target_log_prob_grad_parts,] = mcmc_util.maybe_call_fn_and_grads (target_log_prob_fn,proposed_state_parts) if not proposed_target_log_prob.dtype.is_floating:raise TypeError ('`target_log_prob_fn` must produce a `Tensor` ' 'with `float` `dtype`.') if any (g is None for g in proposed_target_log_prob_grad_parts):raise ValueError ('Encountered `None` gradient. Does your target `target_log_prob_fn` ' 'access all `tf.Variable`s via `tf.get_variable`?
' '  current_state_parts: {}
' '  proposed_state_parts: {}
' '  proposed_target_log_prob_grad_parts: {}'.format (current_state_parts,proposed_state_parts,proposed_target_log_prob_grad_parts)) # Step 3b: Update momentum (again). proposed_momentum_parts = [ v + 0.5 * tf.cast (eps,v.dtype) * g for v,eps,g in zip (proposed_momentum_parts,step_sizes,proposed_target_log_prob_grad_parts) ] return [ proposed_momentum_parts,proposed_state_parts,proposed_target_log_prob,proposed_target_log_prob_grad_parts,]

